import AppKit
import Carbon.HIToolbox

/// Inserts transcribed text into the frontmost app:
/// pasteboard swap + synthetic Cmd-V, then clipboard restore.
///
/// Etiquette learned from Handy/FluidVoice:
/// - tag the transcript with TransientType + AutoGeneratedType so clipboard
///   managers skip it (never ConcealedType - that signals passwords)
/// - guard the restore with changeCount so a copy the user made in the
///   meantime is never clobbered
/// - Cmd-V is posted by PHYSICAL keycode 9, which stays "V" even on the
///   Czech QWERTZ layout (macOS remaps to QWERTY while Cmd is held)
@MainActor
enum TextInjector {
    private static let transientType = NSPasteboard.PasteboardType("org.nspasteboard.TransientType")
    private static let autoGeneratedType = NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType")

    struct Target {
        let pid: pid_t

        static func capture() -> Self? {
            NSWorkspace.shared.frontmostApplication.map { Self(pid: $0.processIdentifier) }
        }

        func matches(foregroundPID: pid_t?) -> Bool { foregroundPID == pid }

        var isCurrent: Bool {
            // Electron and browser editors may expose no stable AX focused element.
            // Cmd-V still targets their real caret; only an app change blocks delivery.
            let matches = matches(foregroundPID: NSWorkspace.shared.frontmostApplication?.processIdentifier)
            if !matches { Log.write("delivery guard: app changed") }
            return matches
        }
    }

    @discardableResult static func insert(
        _ text: String,
        target: Target? = nil,
        pasteboard pb: NSPasteboard = .general,
        postPaste: (() -> Void)? = nil
    ) -> Bool {
        if let target, !target.isCurrent { return false }

        let savedItems = pb.pasteboardItems?.map { item -> [NSPasteboard.PasteboardType: Data] in
            var copy: [NSPasteboard.PasteboardType: Data] = [:]
            for type in item.types {
                if let data = item.data(forType: type) { copy[type] = data }
            }
            return copy
        }

        pb.clearContents()
        let item = NSPasteboardItem()
        item.setString(text, forType: .string)
        item.setData(Data(), forType: transientType)
        item.setData(Data(), forType: autoGeneratedType)
        pb.writeObjects([item])
        let ourChangeCount = pb.changeCount

        if let postPaste {
            postPaste()
        } else {
            let src = CGEventSource(stateID: .combinedSessionState)
            let vDown = CGEvent(keyboardEventSource: src, virtualKey: CGKeyCode(kVK_ANSI_V), keyDown: true)
            let vUp = CGEvent(keyboardEventSource: src, virtualKey: CGKeyCode(kVK_ANSI_V), keyDown: false)
            vDown?.flags = .maskCommand
            vUp?.flags = .maskCommand
            vDown?.post(tap: .cgSessionEventTap)
            vUp?.post(tap: .cgSessionEventTap)
        }

        // Restore the previous clipboard once the paste has landed -
        // but only if nothing else wrote to the pasteboard since.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
            guard pb.changeCount == ourChangeCount else { return }
            let savedItems = savedItems ?? []
            pb.clearContents()
            let restored = savedItems.map { entry -> NSPasteboardItem in
                let item = NSPasteboardItem()
                for (type, data) in entry { item.setData(data, forType: type) }
                return item
            }
            pb.writeObjects(restored)
        }
        return true
    }
}
